// <auto-generated />
using UnityEngine;
using System.Collections.Generic;

namespace Spinnenspiel
{
    public static class JunglePlantFactory
    {
        /// <summary>
        /// Erstellt eine Riesenblatt-Pflanze (Monstera-artig) deterministisch aus seed.
        /// Reine Laufzeit-Mesh-Fabrik, kein Editor-Code.
        /// </summary>
        public static Mesh GiantLeafPlant(int seed)
        {
            var rng = new System.Random(seed);
            float R(float a, float b) => a + (float)rng.NextDouble() * (b - a);

            int nBlatter = rng.Next(3, 8); // 3–7 Blätter
            List<Vector3> allVertices = new List<Vector3>();
            List<int> allTriangles = new List<int>();
            List<Vector2> allUVs = new List<Vector2>();
            List<Vector3> allNormals = new List<Vector3>();

            for (int i = 0; i < nBlatter; i++)
            {
                float stielRadius = R(0.008f, 0.015f);
                float stielLaenge = R(0.3f, 0.9f);
                float azimut = rng.Next(0, 360);
                float neigungVonSenkrechten = R(20f, 45f);
                float stielDirX = Mathf.Cos(azimut * Mathf.Deg2Rad) * Mathf.Sin(neigungVonSenkrechten * Mathf.Deg2Rad);
                float stielDirY = Mathf.Cos(neigungVonSenkrechten * Mathf.Deg2Rad);
                float stielDirZ = Mathf.Sin(azimut * Mathf.Deg2Rad) * Mathf.Sin(neigungVonSenkrechten * Mathf.Deg2Rad);

                for (int side = 0; side < 6; side++)
                {
                    float sideAngle = (side + 0.5f) * 60f * Mathf.Deg2Rad;
                    Vector3 sideDir = new Vector3(
                        Mathf.Cos(sideAngle),
                        0,
                        Mathf.Sin(sideAngle)
                    );
                    Vector3 sideNormal = new Vector3(
                        sideDir.x * stielDirX + sideDir.z * stielDirY,
                        sideDir.y * stielDirX - sideDir.x * stielDirY,
                        sideDir.z * stielDirY + sideDir.y * stielDirX
                    );

                    Vector3 bottomPos = sideDir * stielRadius;
                    Vector3 topPos = sideDir * stielRadius * stielLaenge;

                    allVertices.Add(bottomPos);
                    allNormals.Add(sideNormal.normalized);
                    allUVs.Add(new Vector2(0, 0));

                    allVertices.Add(topPos);
                    allNormals.Add(sideNormal.normalized);
                    allUVs.Add(new Vector2(0, 1));
                }

                for (int tri = 0; tri < 6; tri++)
                {
                    int i1 = tri * 2;
                    int i2 = tri * 2 + 1;
                    int i3 = (tri + 1) * 2;
                    int i4 = (tri + 1) * 2 + 1;

                    allTriangles.Add(i1 + allVertices.Count - 12);
                    allTriangles.Add(i2 + allVertices.Count - 12);
                    allTriangles.Add(i3 + allVertices.Count - 12);
                    allTriangles.Add(i4 + allVertices.Count - 12);
                    allTriangles.Add(i2 + allVertices.Count - 12);
                    allTriangles.Add(i3 + allVertices.Count - 12);
                }

                float blattLaenge = R(0.35f, 1.0f);
                float blattBreite = blattLaenge * R(0.6f, 0.9f);
                float stielEndLae = stielLaenge;
                float azimutBlatt = rng.Next(0, 360);
                float neigungBlatt = R(20f, 45f);
                Vector3 blattFoot = new Vector3(
                    Mathf.Cos(azimutBlatt * Mathf.Deg2Rad) * Mathf.Sin(neigungBlatt * Mathf.Deg2Rad) * stielEndLae,
                    Mathf.Cos(neigungBlatt * Mathf.Deg2Rad) * stielEndLae,
                    Mathf.Sin(azimutBlatt * Mathf.Deg2Rad) * Mathf.Sin(neigungBlatt * Mathf.Deg2Rad) * stielEndLae
                );

                int rasterQuer = 7;
                int rasterLanga = 10;

                for (int r = 0; r < rasterLanga; r++)
                {
                    float tY = (float)r / rasterLanga;
                    float scaleX = (1.0f - tY) * blattLaenge;
                    float scaleY = (1.0f - tY) * blattBreite;

                    for (int c = 0; c < rasterQuer; c++)
                    {
                        float uLocal = (float)c / rasterQuer;
                        float vLocal = (float)r / rasterLanga;

                        float x = uLocal * scaleX;
                        float y = vLocal * scaleY;

                        if (r == rasterLanga - 1)
                        {
                            y -= R(0.1f, 0.25f);
                        }

                        Vector3 leafPos = blattFoot + new Vector3(x, y, 0);
                        Vector3 leafNormal = new Vector3(-blattFoot.x, blattFoot.y, blattFoot.z).normalized;

                        for (int side = 0; side < 6; side++)
                        {
                            float sideAngle = (side + 0.5f) * 60f * Mathf.Deg2Rad;
                            Vector3 sideDir = new Vector3(
                                Mathf.Cos(sideAngle),
                                0,
                                Mathf.Sin(sideAngle)
                            );
                            Vector3 sideNormal = new Vector3(
                                sideDir.x * leafNormal.x + sideDir.z * leafNormal.z,
                                sideDir.y * leafNormal.x - sideDir.x * leafNormal.z,
                                sideDir.z * leafNormal.y + sideDir.y * leafNormal.x
                            );

                            Vector3 leafVert = leafPos + sideDir * y * 0.1f;
                            allVertices.Add(leafVert);
                            allNormals.Add(sideNormal.normalized);
                            allUVs.Add(new Vector2(uLocal, vLocal));
                        }
                    }
                }
            }

            Mesh mesh = new Mesh();
            mesh.name = "GiantLeaf_" + seed;
            if (allVertices.Count > 60000)
            {
                mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            }
            mesh.SetVertices(allVertices);
            mesh.SetTriangles(allTriangles.ToArray(), 0);
            mesh.SetUVs(0, allUVs.ToArray());
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();

            return mesh;
        }

        // Hängende Liane: dünnes 5-seitiges Rohr, das von oben (y≈top) nach unten (y≈0)
        // mit seitlicher Sinus-Schwingung hängt.
        public static Mesh HangingLiana(int seed)
        {
            var rng = new System.Random(seed);
            float R(float a, float b) => a + (float)rng.NextDouble() * (b - a);

            int seg = rng.Next(10, 18);
            float top = R(2.5f, 4.0f);
            float amp = R(0.05f, 0.3f);
            float ph = R(0f, 6.28f);
            float r = R(0.010f, 0.022f);
            int sides = 5;

            var v = new List<Vector3>();
            var t = new List<int>();
            var uv = new List<Vector2>();

            for (int j = 0; j <= seg; j++)
            {
                float f = (float)j / seg;
                Vector3 c = new Vector3(
                    Mathf.Sin(ph + f * 3.14159f) * amp * f,
                    top * (1f - f),
                    Mathf.Cos(ph + f * 3.14159f) * amp * f * 0.5f);
                for (int s = 0; s < sides; s++)
                {
                    float a = s / (float)sides * 6.2831855f;
                    v.Add(c + new Vector3(Mathf.Cos(a) * r, 0f, Mathf.Sin(a) * r));
                    uv.Add(new Vector2(s / (float)sides, f));
                }
                if (j > 0)
                {
                    int cur = j * sides;
                    int prev = (j - 1) * sides;
                    for (int s = 0; s < sides; s++)
                    {
                        int s2 = (s + 1) % sides;
                        t.Add(prev + s);
                        t.Add(prev + s2);
                        t.Add(cur + s);
                        t.Add(prev + s2);
                        t.Add(cur + s2);
                        t.Add(cur + s);
                    }
                }
            }

            var m = new Mesh { name = "HangingLiana_" + seed };
            m.SetVertices(v);
            m.SetTriangles(t, 0);
            m.SetUVs(0, uv);
            m.RecalculateNormals();
            m.RecalculateBounds();
            return m;
        }

        /// <summary>M7-10.5: Spinngscale Laubblatt lieing on the ground (cm-sized).</summary>
        public static Mesh FallenLeaf(int seed)
        {
            var rng = new System.Random(seed);
            float R(float a, float b) => a + (float)rng.NextDouble() * (b - a);

            float len = R(0.03f, 0.06f);
            float wid = len * R(0.5f, 0.8f);
            float curl = R(0f, 0.25f);
            int ribs = rng.Next(3, 6);

            var verts = new List<Vector3>();
            var tris = new List<int>();
            var uvs = new List<Vector2>();

            // Central spine along X, width in Z; slight upward curl at the tip.
            for (int i = 0; i <= ribs; i++)
            {
                float t = (float)i / ribs;
                float x = (t - 0.5f) * len;
                float w = wid * 0.5f * Mathf.Sin(t * Mathf.PI) + 0.002f;
                float y = curl * len * t * t;
                verts.Add(new Vector3(x, y, -w));
                verts.Add(new Vector3(x, y, w));
                uvs.Add(new Vector2(t, 0f));
                uvs.Add(new Vector2(t, 1f));
            }
            for (int i = 0; i < ribs; i++)
            {
                int a = i * 2, b = a + 1, c = a + 2, d = a + 3;
                tris.Add(a); tris.Add(c); tris.Add(b);
                tris.Add(b); tris.Add(c); tris.Add(d);
            }

            var m = new Mesh { name = "FallenLeaf_" + seed };
            m.SetVertices(verts);
            m.SetTriangles(tris, 0);
            m.SetUVs(0, uvs);
            m.RecalculateNormals();
            m.RecalculateBounds();
            return m;
        }

        /// <summary>M7-10.5: Small twig (1–4 cm) lying on the ground.</summary>
        public static Mesh GroundTwig(int seed)
        {
            var rng = new System.Random(seed);
            float len = 0.01f + (float)rng.NextDouble() * 0.03f;
            float r = 0.0015f + (float)rng.NextDouble() * 0.0015f;
            int sides = 5;

            var verts = new List<Vector3>();
            var tris = new List<int>();
            var uvs = new List<Vector2>();

            // Cylinder along X (lying flat), no caps (too small to see).
            for (int s = 0; s <= sides; s++)
            {
                float a = s % sides * (Mathf.PI * 2f / sides);
                float y = Mathf.Cos(a) * r + r; // lie on ground: bottom at y=0
                float z = Mathf.Sin(a) * r;
                verts.Add(new Vector3(-len * 0.5f, y, z));
                verts.Add(new Vector3(len * 0.5f, y, z));
                uvs.Add(new Vector2(0f, (float)s / sides));
                uvs.Add(new Vector2(1f, (float)s / sides));
            }
            for (int s = 0; s < sides; s++)
            {
                int a0 = s * 2, b0 = a0 + 1, c0 = a0 + 2, d0 = a0 + 3;
                tris.Add(a0); tris.Add(c0); tris.Add(b0);
                tris.Add(b0); tris.Add(c0); tris.Add(d0);
            }

            var m = new Mesh { name = "GroundTwig_" + seed };
            m.SetVertices(verts);
            m.SetTriangles(tris, 0);
            m.SetUVs(0, uvs);
            m.RecalculateNormals();
            m.RecalculateBounds();
            return m;
        }

        /// <summary>
        /// WALD6: Jungbaeumchen/Nadelwedel (Coniferen-Saling) as Gebuesch, deterministic from seed.
        /// Central stem + 3-5 whorls of needle twigs (thin cones), total height normalised to ~1 m
        /// so the generator can scale it to 0.5..2 m. Real geometry -> opaque material (no cutout).
        /// </summary>
        public static Mesh YoungConifer(int seed)
        {
            var rng = new System.Random(seed);
            float R(float a, float b) => a + (float)rng.NextDouble() * (b - a);

            var verts = new List<Vector3>();
            var tris = new List<int>();
            var norms = new List<Vector3>();

            // Central stem: 6-sided cone from y=0 to y=1, thin at top.
            const int sides = 6;
            for (int s = 0; s < sides; s++)
            {
                float a0 = s * (Mathf.PI * 2f / sides);
                float a1 = (s + 1) * (Mathf.PI * 2f / sides);
                float rB = 0.02f, rT = 0.006f;
                int b = verts.Count;
                verts.Add(new Vector3(Mathf.Cos(a0) * rB, 0f, Mathf.Sin(a0) * rB));
                verts.Add(new Vector3(Mathf.Cos(a1) * rB, 0f, Mathf.Sin(a1) * rB));
                verts.Add(new Vector3(Mathf.Cos(a1) * rT, 1f, Mathf.Sin(a1) * rT));
                verts.Add(new Vector3(Mathf.Cos(a0) * rT, 1f, Mathf.Sin(a0) * rT));
                Vector3 n = new Vector3(Mathf.Cos((a0 + a1) * 0.5f), 0.2f, Mathf.Sin((a0 + a1) * 0.5f)).normalized;
                for (int k = 0; k < 4; k++) norms.Add(n);
                tris.Add(b); tris.Add(b + 1); tris.Add(b + 2);
                tris.Add(b); tris.Add(b + 2); tris.Add(b + 3);
            }

            // Needle twigs: whorls at 4 heights, each twig a thin tapered quad-strip pair (billon).
            int whorls = rng.Next(3, 6);
            for (int w = 0; w < whorls; w++)
            {
                float y = 0.25f + w * (0.7f / Mathf.Max(1, whorls - 1)) * 0.95f;
                float len = R(0.18f, 0.34f) * (1.15f - y * 0.6f);
                int twigs = rng.Next(5, 8);
                float baseAng = rng.Next(0, 360) * Mathf.Deg2Rad;
                for (int t = 0; t < twigs; t++)
                {
                    float ang = baseAng + t * (Mathf.PI * 2f / twigs) + R(-0.15f, 0.15f);
                    float dx = Mathf.Cos(ang), dz = Mathf.Sin(ang);
                    float rise = R(0.12f, 0.3f) * len;
                    float wHalf = R(0.012f, 0.024f);
                    int b = verts.Count;
                    Vector3 p0 = new Vector3(dx * 0.02f, y, dz * 0.02f);
                    Vector3 p1 = new Vector3(dx * len, y + rise, dz * len);
                    Vector3 sideV = new Vector3(-dz, 0f, dx) * wHalf;
                    verts.Add(p0 - sideV); verts.Add(p0 + sideV);
                    verts.Add(p1 + sideV + Vector3.up * 0.004f); verts.Add(p1 - sideV + Vector3.up * 0.004f);
                    for (int k = 0; k < 4; k++) norms.Add(Vector3.up);
                    tris.Add(b); tris.Add(b + 1); tris.Add(b + 2);
                    tris.Add(b); tris.Add(b + 2); tris.Add(b + 3);
                }
            }

            var m = new Mesh { name = "YoungConifer_" + seed };
            m.SetVertices(verts);
            m.SetTriangles(tris, 0);
            m.SetNormals(norms);
            // Flat UV (texture centre): no per-vertex mapping needed, tint comes from MPB _BaseColor.
            var uvs = new Vector2[verts.Count];
            for (int u = 0; u < uvs.Length; u++) uvs[u] = new Vector2(0.5f, 0.5f);
            m.SetUVs(0, uvs);
            m.RecalculateBounds();
            return m;
        }
